class Strategy(BaseStrategy):
    """
    Benevolent Adaptive Strategy (BAS).

    Adapts cooperation based on current stock level and the observed
    number of cooperating opponents in the previous round.  The
    thresholds are computed once from the known capacity.
    """

    def __init__(self, game_description: CommonPoolDescription):
        # store game parameters
        self.game_description = game_description
        self.n = game_description.n_players
        self.r = game_description.n_rounds
        self.cap = float(game_description.capacity)

        # pre‑compute stock tiers
        self.high = 0.75 * self.cap          # abundant
        self.medium = 0.40 * self.cap        # moderate
        self.low = 0.20 * self.cap           # scarce (not directly used)

    def __call__(self, history: PlayerHistory, current_stock: float) -> Action:
        # current round index (0‑based)
        t = history.round_number

        # determine number of cooperating opponents in previous round
        if t == 0:
            # assume full cooperation before the game starts
            c_prev = self.n - 1
        else:
            c_prev = int(history.opponent_cooperators[-1])

        # final round: defect to harvest remaining stock
        if t == self.r - 1:
            return Action.D

        # stock is zero → consumption would be zero regardless; cooperate
        if current_stock == 0.0:
            return Action.C

        # helper: proportion of cooperating opponents (avoid division by zero)
        if self.n > 1:
            coop_frac = c_prev / (self.n - 1)
        else:
            coop_frac = 0.0

        # decision branches based on stock level
        if current_stock >= self.high:
            # abundant stock
            if coop_frac >= 0.5:
                return Action.C
            else:
                return Action.D

        elif current_stock >= self.medium:
            # moderate stock – proportional reciprocity
            if random.random() < coop_frac:
                return Action.C
            else:
                return Action.D

        else:
            # low / moderate‑low stock
            if coop_frac >= 0.75:
                return Action.C
            else:
                return Action.D
